def areOccurrencesEqual(s):
    # Create a frequency array for 26 lowercase letters
    counts = [0] * 26

    # Count each character's occurrences
    for char in s:
        idx = ord(char) - ord('a')
        counts[idx] += 1

    # Find the target count: the first nonzero count
    target = None
    for freq in counts:
        if freq > 0:
            if target is None:
                target = freq
            elif freq != target:
                return False
    return True
